import{_ as a,o as t,c as p,a3 as r}from"./chunks/framework.BwzYn71E.js";const m=JSON.parse('{"title":"阻尼理论-改","description":"","frontmatter":{"translationSource":{"title":"阻尼理论-改","archivedAt":"2026-10-27","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=WJNJBOl9tQtVZ0GEuD8UaP","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/damping-theory-revised"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/damping-theory-revised"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/damping-theory-revised"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/damping-theory-revised"}]]},"headers":[],"relativePath":"zh/damping-theory-revised.md","filePath":"zh/page-WJNJBOl9tQtVZ0GEuD8UaP.md"}'),i={name:"zh/damping-theory-revised.md"};function o(n,e,d,s,l,c){return t(),p("div",null,[...e[0]||(e[0]=[r('<div class="logistics-content"><span class="logistics-source-anchor" id="阻尼理论-改" aria-hidden="true"></span><h1 id="阻尼理论-改" tabindex="-1">阻尼理论-改 <a class="header-anchor" href="#阻尼理论-改" aria-label="Permalink to &quot;阻尼理论-改&quot;">​</a></h1><blockquote><p>源页面 ID：<code>WJNJBOl9tQtVZ0GEuD8UaP</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=WJNJBOl9tQtVZ0GEuD8UaP" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>阻尼理论由@jnk 创作并整理维护，当前版本缺少足够量的验证</p><p><span class="mark-red">阻尼理论已经过时，最新理论请参见</span><a href="/endfield-skydoc/zh/introduction-to-analyzing-endfield-logistics-bugs">终末地物流bug分析导论</a>，出于已归档与去重考虑，这里的图片已经移除。</p><p>特殊的，反应池与扩容反应池的优先输入输出不能包含在该理论下，应当从<a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=NWZEGRxknMJsjvUO7PQZXj&amp;client_hint=0" target="_blank" rel="noreferrer">反应池特性研究整理</a>中查看其特殊性质。</p><p>这里使用物流线的说法，<em>物流线</em>：</p><p>简单来说，物流线是从工厂出口到物流结构末尾所有可能的物品路线，如红线所示。末尾没有连接到工厂的将末尾物流元件视为工厂。这里将所有的中间物流元件视为物流线的一部分</p><p><em>物流线的阻尼</em>：</p><p>物流线上的物流元件个数为其的阻尼，整个传送带被视为一个物流元件，物流桥的不同方向被视为不同物流元件。紧贴工厂入口且有其他下游的分流器忽略连接到这个工厂的物流线，同时这里也不会影响接下来的连接顺序判定。</p><p><em>末端序(连接顺序)</em>：</p><p>具体的，当物流元件直接连接工厂入口时</p><p>如果（该物流元件非分流器）且（该工厂其他入口有非分流器已经加入了末端序），则添加到已有的非分流器物流元件处，否则添加到末尾</p><p>当物流元件被删除或其连接的工厂被删除时，自然的，其将会从连接顺序中被删去并且重新计算相关的放置顺序改变（例如变成断尾后，末端物流元件会被视为早已经存在的工厂）</p><p>特别的，末端序同时也是优先输入的优先级，末端序越靠前的端口，优先级越高，同一位则轮询。</p><p><span class="mark-red">此处需补充计算图例</span></p><p><em>出口阻尼</em></p><p>每个出口可能对应多个物流线，但是其只会选取其中一个的阻尼作为出口阻尼，即一个出口只有一个阻尼，具体计算见阻尼理论。</p><p><em>阻尼理论</em></p><p>一种解释工厂出口有时存在优先级现象时的理论，我们说阻尼理论时通常是在解释优先输出现象。</p><p>按照末端序取出一位（可能有多个合并）末端物流元件：</p><p>执行从下游向上游进行的BFS，标记上游阻尼为下游阻尼加一，并添加访问标记防止重复访问。</p><p>特判工厂出口的没有连接下游的单个物流元件，假如该物流元件比上游工厂早被连接，则阻尼为不会发生同化的无穷大，否则为会被同化的无穷小。</p><p>对于同一个工厂的多个出口，使其中所有非汇流器开头的出口变成相同的最大的阻尼。这被称为同化。</p><p>最后，阻尼小的出口优先级高，先放下开头的物流元件的出口优先度高。先看优先级，再看优先度。对于非汇流器开头的那些出口，如果优先，会在其中轮询。</p><p><span class="mark-red">此处需补充计算图例</span></p></div>',1)])])}const k=a(i,[["render",o]]);export{m as __pageData,k as default};
